<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue';import {api,type Order,type Profile} from '../api';import {useSession} from '../store';import {ElMessage,ElMessageBox} from 'element-plus';
const session=useSession(),orders=ref<Order[]>([]), techs=ref<Profile[]>([]),total=ref(0),page=ref(1),dialog=ref(false),detail=ref<Order|null>(null),history=ref<any[]>([]),loading=ref(false),selectedTech=ref<number>(),userDialog=ref(false),userList=ref<Profile[]>([]),userTotal=ref(0),userPage=ref(1),images=ref<{id:number;contentType:string}[]>([]),feedback=ref<any>(null),rating=ref(5),comment=ref(''),uploading=ref(false);
const form=reactive({building:'',room:'',category:'下水道',description:'',urgency:'NORMAL'});
const labels:Record<string,string>={PENDING_REVIEW:'待受理',PENDING_ASSIGNMENT:'待派单',PENDING_ACCEPTANCE:'待接单',IN_PROGRESS:'处理中',PENDING_CONFIRMATION:'待确认',COMPLETED:'已完成',CANCELLED:'已取消'};
async function load(){loading.value=true;try{const r:any=await api.get('/orders',{params:{page:page.value,size:20}});orders.value=r.data.items;total.value=r.data.total}finally{loading.value=false}}
async function init(){await session.load();if(session.user?.role==='ADMIN'){const r:any=await api.get('/users/technicians');techs.value=r.data}await load()}
async function create(){if(!form.building.trim()||!form.room.trim()||!form.description.trim()){ElMessage.warning('请填写楼栋、房间和故障描述');return}await api.post('/orders',form);dialog.value=false;form.description='';ElMessage.success('报修已提交');page.value=1;await load()}
async function inspect(o:Order){detail.value=o;const [h,imgs,f]:any[]=await Promise.all([api.get(`/orders/${o.id}/history`),api.get(`/orders/${o.id}/images`),api.get(`/orders/${o.id}/feedback`)]);history.value=h.data;images.value=imgs.data;feedback.value=f.data;rating.value=5;comment.value=''}
async function uploadImage(e:Event){const input=e.target as HTMLInputElement;const file=input.files?.[0];if(!file||!detail.value)return;if(file.size>3*1024*1024){ElMessage.warning('图片不能超过 3 MB');input.value='';return}const body=new FormData();body.append('file',file);uploading.value=true;try{await api.post(`/orders/${detail.value.id}/images`,body);ElMessage.success('图片已上传');await inspect(detail.value)}finally{uploading.value=false;input.value=''}}
async function viewImage(id:number){if(!detail.value)return;const blob=await api.get(`/orders/${detail.value.id}/images/${id}`,{responseType:'blob'}) as unknown as Blob;const url=URL.createObjectURL(blob);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function submitFeedback(){if(!detail.value)return;await api.post(`/orders/${detail.value.id}/feedback`,{rating:rating.value,comment:comment.value});ElMessage.success('评价已提交');await inspect(detail.value)}
async function act(o:Order,action:string,payload:object={}){if(action==='finish'){const answer=await ElMessageBox.prompt('请填写维修结果','完成维修',{inputType:'textarea',inputValidator:v=>!!v?.trim()||'请填写维修结果'});payload={result:answer.value}}await api.post(`/orders/${o.id}/actions/${action}`,payload);ElMessage.success('操作成功');detail.value=null;await load()}
async function loadUsers(){const r:any=await api.get('/users',{params:{page:userPage.value,size:20}});userList.value=r.data.items;userTotal.value=r.data.total}
async function showUsers(){await loadUsers();userDialog.value=true}
async function roleChange(id:number,role:string){await api.put(`/users/${id}/role`,{role});const r:any=await api.get('/users/technicians');techs.value=r.data;await loadUsers();ElMessage.success('角色已更新')}
onMounted(init);
</script>
<template><div class="shell"><header><div class="brand"><span class="brand-icon">✳</span><span>AI Repair Hub<small>校园维修服务平台</small></span></div><div class="account"><span>{{ session.user?.username }} · {{ {STUDENT:'学生',ADMIN:'管理员',TECHNICIAN:'维修人员'}[session.user?.role||'STUDENT'] }}</span><el-button text @click="session.logout()">退出</el-button></div></header><main class="content"><section class="hero"><div><p class="eyebrow">CAMPUS REPAIR SERVICE</p><h1>{{ session.user?.role==='STUDENT'?'宿舍有问题？交给我们。':'维修工作台' }}</h1><p class="muted">{{ session.user?.role==='STUDENT'?'提交报修，随时掌握处理进度。':'查看工单，及时推进处理进度。' }}</p><el-button v-if="session.user?.role==='STUDENT'" type="primary" size="large" @click="dialog=true">＋ 发起报修</el-button><el-button v-if="session.user?.role==='ADMIN'" @click="showUsers">用户与角色</el-button></div><div class="hero-art">⌂<span>安心住，轻松修</span></div></section><section class="panel"><div class="panel-head"><div><h2>{{ session.user?.role==='STUDENT'?'我的报修':'工单列表' }}</h2><p class="muted">共 {{total}} 条记录</p></div><el-button @click="load">刷新</el-button></div><div v-loading="loading"><div v-if="!orders.length" class="empty">暂无工单</div><article v-for="o in orders" :key="o.id" class="order"><div class="order-main" @click="inspect(o)"><div class="order-title">{{ o.category }} <span class="status">{{ labels[o.status]||o.status }}</span></div><p>{{o.description}}</p><small>{{o.building}} · {{o.room}}　#{{o.id}}　{{o.createdAt?.replace('T',' ')}}</small></div><div class="actions"><el-button v-if="session.user?.role==='ADMIN'&&o.status==='PENDING_REVIEW'" type="primary" plain @click="act(o,'approve')">受理</el-button><template v-if="session.user?.role==='ADMIN'&&o.status==='PENDING_ASSIGNMENT'"><el-select v-model="selectedTech" placeholder="选择维修人员" style="width:150px"><el-option v-for="t in techs" :key="t.id" :label="t.username" :value="t.id" /></el-select><el-button type="primary" @click="selectedTech?act(o,'assign',{technicianId:selectedTech}):ElMessage.warning('请选择维修人员')">派单</el-button></template><el-button v-if="session.user?.role==='TECHNICIAN'&&o.status==='PENDING_ACCEPTANCE'" type="primary" @click="act(o,'accept')">接单</el-button><el-button v-if="session.user?.role==='TECHNICIAN'&&o.status==='IN_PROGRESS'" type="primary" @click="act(o,'finish')">完成维修</el-button><el-button v-if="session.user?.role==='STUDENT'&&o.status==='PENDING_CONFIRMATION'" type="primary" @click="act(o,'confirm')">确认完成</el-button><el-button v-if="session.user?.role==='STUDENT'&&['PENDING_REVIEW','PENDING_ASSIGNMENT'].includes(o.status)" @click="act(o,'cancel')">取消</el-button></div></article></div><el-pagination v-if="total>20" layout="prev, pager, next" :total="total" :page-size="20" v-model:current-page="page" @current-change="load" /></section><section v-if="session.user?.role==='STUDENT'" class="notice">AI 智能助手与维修知识库正在建设中。遇到电路、燃气或严重漏水等问题，请远离危险区域并联系宿管或专业人员。</section></main>
<el-dialog v-model="userDialog" title="用户与角色" width="min(650px, 92vw)"><p class="muted">用户先注册学生账号，管理员可在这里调整角色。</p><el-table :data="userList"><el-table-column prop="id" label="ID" width="70"/><el-table-column prop="username" label="用户名"/><el-table-column prop="role" label="角色"/><el-table-column label="操作" width="220"><template #default="scope"><el-button v-if="scope.row.id!==session.user?.id" size="small" @click="roleChange(scope.row.id,scope.row.role==='TECHNICIAN'?'STUDENT':'TECHNICIAN')">{{scope.row.role==='TECHNICIAN'?'设为学生':'设为维修人员'}}</el-button></template></el-table-column></el-table><el-pagination v-if="userTotal>20" v-model:current-page="userPage" :total="userTotal" :page-size="20" layout="prev, pager, next" @current-change="loadUsers"/></el-dialog>
<el-dialog v-model="dialog" title="填写报修信息" width="min(560px, 92vw)"><el-form label-position="top"><div class="grid"><el-form-item label="宿舍楼"><el-input v-model="form.building" maxlength="100" placeholder="例如：3 号楼" /></el-form-item><el-form-item label="宿舍号"><el-input v-model="form.room" maxlength="30" placeholder="例如：302" /></el-form-item></div><el-form-item label="故障类别"><el-select v-model="form.category"><el-option v-for="c in ['下水道','水龙头','空调','灯具','其他']" :key="c" :label="c" :value="c" /></el-select></el-form-item><el-form-item label="故障描述"><el-input v-model="form.description" type="textarea" :rows="4" maxlength="2000" show-word-limit placeholder="请描述故障现象和具体位置" /></el-form-item><el-form-item label="紧急程度"><el-radio-group v-model="form.urgency"><el-radio value="LOW">低</el-radio><el-radio value="NORMAL">普通</el-radio><el-radio value="HIGH">紧急</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">提交报修</el-button></template></el-dialog>
<el-dialog :model-value="!!detail" @close="detail=null" title="工单详情与操作记录" width="min(600px, 92vw)"><template v-if="detail"><p>{{detail.description}}</p><p>维修结果：{{detail.result||'暂无'}}</p><h4>工单图片</h4><p v-if="!images.length" class="muted">暂无图片</p><el-button v-for="(img,index) in images" :key="img.id" size="small" @click="viewImage(img.id)">查看图片 {{index+1}}</el-button><p v-if="(session.user?.role==='STUDENT'&&['PENDING_REVIEW','PENDING_ASSIGNMENT'].includes(detail.status))||(session.user?.role==='TECHNICIAN'&&detail.status==='IN_PROGRESS')"><label>上传图片（JPEG/PNG，单张不超过 3 MB，最多 6 张）<input type="file" accept="image/jpeg,image/png" :disabled="uploading" @change="uploadImage" /></label></p><h4 v-if="detail.status==='COMPLETED'">维修评价</h4><div v-if="feedback">{{feedback.rating||feedback.RATING}} 星 · {{feedback.comment||feedback.COMMENT||'未填写文字'}}</div><div v-else-if="detail.status==='COMPLETED'&&session.user?.role==='STUDENT'"><el-rate v-model="rating"/><el-input v-model="comment" maxlength="500" show-word-limit type="textarea" placeholder="分享你的维修体验（选填）"/><el-button type="primary" @click="submitFeedback">提交评价</el-button></div><el-timeline><el-timeline-item v-for="h in history" :key="h.id" :timestamp="String(h.created_at||h.CREATED_AT||'')">{{h.action||h.ACTION}} · {{labels[h.to_status||h.TO_STATUS]||h.to_status||h.TO_STATUS}}</el-timeline-item></el-timeline></template></el-dialog></div></template>
